all8_complete_headers_must_remain_rawexa.card_decompositionCarrier_le:
private theorem card_decompositionCarrier_le {S H F : ℝ}
    (hS : 1 ≤ S) (hH : 1 ≤ H) (hF : 1 ≤ F) {zy : ℕ × ℤ}
    (hzy : zy ∈ (sourceCarrier S H F).image output) :
    (decompositionCarrier S H F zy).card ≤ divisorMaximum S H F ^ 2

all8_complete_headers_must_remain_rawexa.tau_le_divisorMaximum:
private theorem tau_le_divisorMaximum {S H F : ℝ} {n : ℕ}
    (hn : 0 < n) (hbound : (n : ℝ) ≤ max (4 * S ^ 2) (8 * F * H * S)) :
    n.divisors.card ≤ divisorMaximum S H F
